package dev.rodrigosambade.oca;
import java.util.*;
public final class GooseGame{public static final int LAST=62;public record Move(int from,int rolled,int to,boolean extraTurn,int skipTurns,String message,boolean won){}private static final Map<Integer,Integer>GEESE=Map.ofEntries(Map.entry(4,8),Map.entry(8,13),Map.entry(13,17),Map.entry(17,22),Map.entry(22,26),Map.entry(26,31),Map.entry(31,35),Map.entry(35,40),Map.entry(40,44),Map.entry(44,49),Map.entry(49,53),Map.entry(53,58));public Move apply(int from,int roll){if(from<0||from>LAST||roll<1||roll>6)throw new IllegalArgumentException();int p=from+roll;if(p>LAST)p=LAST-(p-LAST);boolean extra=false;int skip=0;String msg="";if(GEESE.containsKey(p)){p=GEESE.get(p);extra=true;msg="De oca a oca y tiro porque me toca";}else if(p==5){p=11;extra=true;msg="De puente a puente y tiro porque me lleva la corriente";}else if(p==11){p=5;extra=true;msg="De puente a puente y tiro porque me lleva la corriente";}else if(p==25){p=52;extra=true;msg="De dado a dado y tiro porque me ha tocado";}else if(p==52){p=25;extra=true;msg="De dado a dado y tiro porque me ha tocado";}else if(p==18){skip=2;msg="Posada: pierdes 2 turnos";}else if(p==30){skip=2;msg="Pozo: pierdes 2 turnos";}else if(p==41){p=29;msg="Laberinto: vuelves a la casilla 30";}else if(p==51){skip=3;msg="Cárcel: pierdes 3 turnos";}else if(p==57){p=0;msg="Muerte: vuelves a empezar";}return new Move(from,roll,p,extra,skip,msg,p==LAST);}}
